SELECT p.id, p.symbol, p.opened_at, p.closed_at, p.realized_pnl, (SELECT COUNT(*) FROM trade_signal s WHERE s.symbol = p.symbol AND s.interval_code = '1h' AND s.generated_at > p.opened_at AND s.generated_at <= p.closed_at) AS new_1h_during_hold, (SELECT s2.decision FROM trade_signal s2 WHERE s2.symbol = p.symbol AND s2.interval_code = '1h' AND s2.generated_at <= p.opened_at ORDER BY s2.generated_at DESC LIMIT 1) AS one_hour_at_entry FROM paper_position p WHERE p.close_reason = 'HTF_SELL_CONFIRMED' AND p.closed_at BETWEEN '2026-10-10 00:15:21' AND '2026-10-11 07:00:03' ORDER BY p.closed_at LIMIT 200